const AMVGG_DEMAND_STARS = {
  "High": 3,
  "Medium": 2,
  "Low": 1,
  "Decent": 1
};
const AMVGG_DEMAND_MULTIPLIER = {
  "1": 61,
  "2": 64,
  "3": 67
};
const AMVGG_USD_SCALE = 1.725;

function roundUsd(raw) {
  if (!Number.isFinite(raw)) return null;
  if (raw >= 50) return Math.round(raw);
  if (raw >= 10) return Math.ceil(raw * 2) / 2;
  if (raw < 1) return Math.round(raw * 100) / 100;
  return Math.ceil(raw * 10) / 10;
}

function computeUsdFromFrost(frostValue, demandStars) {
  const stars = Number(demandStars);
  const multiplier =
    AMVGG_DEMAND_MULTIPLIER[stars] ||
    AMVGG_DEMAND_MULTIPLIER[String(stars)];
  if (!multiplier || !Number.isFinite(frostValue)) return null;
  // 3★ → 67×value/1.725 | 2★ → 64×value/1.725 | 1★ → 61×value/1.725
  return roundUsd((frostValue * multiplier) / AMVGG_USD_SCALE);
}

function buildPotionKey(potions) {
  const fly = potions && potions.fly;
  const ride = potions && potions.ride;
  const neon = potions && potions.neon;
  const mega = potions && potions.mega;
  return (mega ? 'm' : '') + (neon ? 'n' : '') + (fly ? 'f' : '') + (ride ? 'r' : '');
}

/** Potion keys used for pet USD overrides / editors (blank = no potions). */
var AMVGG_PET_VARIANT_KEYS = ['', 'f', 'r', 'fr', 'n', 'nf', 'nr', 'nfr', 'm', 'mf', 'mr', 'mfr'];

/** Keys shown in the site value editor (FR / NFR / MFR are omitted). */
var AMVGG_PET_EDITOR_VARIANT_KEYS = ['', 'f', 'r', 'n', 'nf', 'nr', 'm', 'mf', 'mr'];

function potionsFromKey(key) {
  const k = String(key || '');
  return {
    mega: k.indexOf('m') !== -1,
    neon: k.indexOf('n') !== -1,
    fly: k.indexOf('f') !== -1,
    ride: k.indexOf('r') !== -1,
  };
}

function petOverrideHasExtendedVariants(entry) {
  if (!entry || typeof entry !== 'object') return false;
  return AMVGG_PET_VARIANT_KEYS.some(
    (k) =>
      k !== 'fr' &&
      k !== 'nfr' &&
      k !== 'mfr' &&
      Object.prototype.hasOwnProperty.call(entry, k) &&
      Number.isFinite(Number(entry[k]))
  );
}

function resolvePetOverrideUsd(entry, potions) {
  if (!entry || typeof entry !== 'object') return null;
  const key = buildPotionKey(potions || {});
  if (Object.prototype.hasOwnProperty.call(entry, key)) {
    const exact = Number(entry[key]);
    if (Number.isFinite(exact) && exact >= 0) return exact;
  }

  // Legacy overrides only stored FR / NFR / MFR buckets.
  if (!petOverrideHasExtendedVariants(entry)) {
    const p = potions || {};
    if (p.mega) {
      const mfr = Number(entry.mfr);
      return Number.isFinite(mfr) && mfr >= 0 ? mfr : null;
    }
    if (p.neon) {
      const nfr = Number(entry.nfr);
      return Number.isFinite(nfr) && nfr >= 0 ? nfr : null;
    }
    const fr = Number(entry.fr);
    return Number.isFinite(fr) && fr >= 0 ? fr : null;
  }

  return null;
}

function computeCategoryValues(category, regular, neon, mega, coefficients) {
  const coef = coefficients[String(category)];
  if (!coef) return null;

  const precision = [4, 4];
  if (regular >= 0.0175) precision[0] = 3;
  if (category === 11 && regular > 0.08) {
    return {
      NP: Number((0.95 * regular).toFixed(precision[0])),
      R: Number((0.975 * regular).toFixed(precision[0])),
      F: Number((0.975 * regular).toFixed(precision[0])),
      NNP: Number((neon * coef.NNP).toFixed(precision[1])),
      NR: neon > 0.2 ? neon : Number((neon * coef.NR).toFixed(precision[1])),
      NF: neon > 0.2 ? neon : Number((neon * coef.NF).toFixed(precision[1])),
      MNP: Number((mega * coef.MNP).toFixed(precision[1])),
      MR: mega > 0.9 ? mega : Number((mega * coef.MR).toFixed(precision[1])),
      MF: mega > 0.9 ? mega : Number((mega * coef.MF).toFixed(precision[1])),
    };
  }

  return {
    NP: Number((regular * coef.NP).toFixed(precision[0])),
    R: Number((regular * coef.R).toFixed(precision[0])),
    F: Number((regular * coef.F).toFixed(precision[0])),
    NNP: Number((neon * coef.NNP).toFixed(precision[1])),
    NR: Number((neon * coef.NR).toFixed(precision[1])),
    NF: Number((neon * coef.NF).toFixed(precision[1])),
    MNP: Number((mega * coef.MNP).toFixed(precision[1])),
    MR: Number((mega * coef.MR).toFixed(precision[1])),
    MF: Number((mega * coef.MF).toFixed(precision[1])),
  };
}

function getPetFrostValue(pet, potions) {
  const key = buildPotionKey(potions);
  if (pet.category === 13) {
    switch (key) {
      case 'fr':
      default:
        return pet.regularValue;
      case 'r':
        return pet.rValue;
      case 'f':
        return pet.fValue;
      case '':
        return pet.npRegularValue;
      case 'nfr':
        return pet.neonValue;
      case 'nr':
        return pet.nrValue;
      case 'nf':
        return pet.nfValue;
      case 'n':
        return pet.npNeonValue;
      case 'mfr':
        return pet.megaValue;
      case 'mr':
        return pet.mrValue;
      case 'mf':
        return pet.mfValue;
      case 'm':
        return pet.npMegaValue;
    }
  }

  const computed = computeCategoryValues(
    pet.category,
    pet.regularValue,
    pet.neonValue,
    pet.megaValue,
    AMVGG_CATEGORY_COEFFICIENTS
  );
  if (!computed) return pet.regularValue;

  switch (key) {
    case 'fr':
    default:
      return pet.regularValue;
    case 'r':
      return computed.R;
    case 'f':
      return computed.F;
    case '':
      return computed.NP;
    case 'nfr':
      return pet.neonValue;
    case 'nr':
      return computed.NR;
    case 'nf':
      return computed.NF;
    case 'n':
      return computed.NNP;
    case 'mfr':
      return pet.megaValue;
    case 'mr':
      return computed.MR;
    case 'mf':
      return computed.MF;
    case 'm':
      return computed.MNP;
  }
}

function getPetDemandLabel(pet, potions) {
  const key = buildPotionKey(potions);
  if (pet.category === 13) {
    switch (key) {
      case 'fr':
      default:
        return pet.regularDemand;
      case 'r':
        return pet.rDemand;
      case 'f':
        return pet.fDemand;
      case '':
        return pet.npRegularDemand;
      case 'nfr':
        return pet.neonDemand;
      case 'nr':
        return pet.nrDemand;
      case 'nf':
        return pet.nfDemand;
      case 'n':
        return pet.npNeonDemand;
      case 'mfr':
        return pet.megaDemand;
      case 'mr':
        return pet.mrDemand;
      case 'mf':
        return pet.mfDemand;
      case 'm':
        return pet.npMegaDemand;
    }
  }

  if (potions && potions.neon) return pet.neonDemand;
  if (potions && potions.mega) return pet.megaDemand;
  return pet.regularDemand;
}

function getPetUsdValue(pet, potions) {
  const frost = getPetFrostValue(pet, potions);
  const demandLabel = getPetDemandLabel(pet, potions);
  const demandStars = AMVGG_DEMAND_STARS[demandLabel] || 0;
  return computeUsdFromFrost(frost, demandStars);
}


function formatUsdValue(amount) {
  if (amount == null || !Number.isFinite(amount)) return '—';
  if (Number.isInteger(amount)) return '$' + amount.toLocaleString('en-US');
  if (amount < 1) return '$' + amount.toFixed(2);
  return '$' + amount.toFixed(1);
}

function getAmvggUsdValue(itemName, potions) {
  const overrides = typeof globalThis !== 'undefined' ? globalThis.__VALUE_OVERRIDES : null;
  if (overrides && itemName) {
    if (overrides.pets && Object.prototype.hasOwnProperty.call(overrides.pets, itemName)) {
      const entry = overrides.pets[itemName];
      const resolved = resolvePetOverrideUsd(
        entry,
        potions || { fly: true, ride: true, neon: false, mega: false }
      );
      if (resolved != null) return resolved;
    }
    if (overrides.items && Object.prototype.hasOwnProperty.call(overrides.items, itemName)) {
      const flat = Number(overrides.items[itemName]);
      return Number.isFinite(flat) ? flat : null;
    }
  }

  if (Object.prototype.hasOwnProperty.call(AMVGG_PET_PRICING, itemName)) {
    return getPetUsdValue(AMVGG_PET_PRICING[itemName], potions || { fly: true, ride: true, neon: false, mega: false });
  }
  return Object.prototype.hasOwnProperty.call(AMVGG_USD_VALUES, itemName)
    ? AMVGG_USD_VALUES[itemName]
    : null;
}

function getTradeItemUsdValue(item) {
  if (!item || item.isSign) return 0;
  if (typeof item.usdValue === 'number' && Number.isFinite(item.usdValue)) {
    return item.usdValue;
  }
  const name = item.name;
  if (!name) return 0;
  const potions = item.potions || { fly: false, ride: false, neon: false, mega: false };
  return getAmvggUsdValue(name, potions) || 0;
}

function sumTradeSideUsd(items) {
  if (!Array.isArray(items)) return 0;
  return items.reduce((total, item) => total + getTradeItemUsdValue(item), 0);
}

function formatTradeSideLabel(label, total) {
  return label + ': ' + formatUsdValue(total);
}

function getItemListSortUsd(name) {
  const overrides = typeof globalThis !== 'undefined' ? globalThis.__VALUE_OVERRIDES : null;
  if (overrides && overrides.pets && Object.prototype.hasOwnProperty.call(overrides.pets, name)) {
    const fromOverride = resolvePetOverrideUsd(overrides.pets[name], {
      fly: true,
      ride: true,
      neon: false,
      mega: false,
    });
    if (fromOverride != null) return fromOverride;
  }
  if (overrides && overrides.items && Object.prototype.hasOwnProperty.call(overrides.items, name)) {
    return overrides.items[name];
  }
  if (Object.prototype.hasOwnProperty.call(AMVGG_PET_PRICING, name)) {
    const usd = getPetUsdValue(AMVGG_PET_PRICING[name], { fly: true, ride: true, neon: false, mega: false });
    return usd == null ? -1 : usd;
  }
  if (Object.prototype.hasOwnProperty.call(AMVGG_USD_VALUES, name)) {
    return AMVGG_USD_VALUES[name];
  }
  return -1;
}

function sortItemsByUsdDesc(items) {
  return [...items].sort((a, b) => {
    const diff = getItemListSortUsd(b.name) - getItemListSortUsd(a.name);
    return diff !== 0 ? diff : a.name.localeCompare(b.name);
  });
}

function sortNamedListInPlaceByUsd(list) {
  if (!Array.isArray(list)) return;
  const sorted = sortItemsByUsdDesc(list);
  list.splice(0, list.length, ...sorted);
}

function sortAllCatalogListsByUsd() {
  if (typeof pets !== 'undefined') sortNamedListInPlaceByUsd(pets);
  if (typeof petWear !== 'undefined') sortNamedListInPlaceByUsd(petWear);
  if (typeof strollers !== 'undefined') sortNamedListInPlaceByUsd(strollers);
  if (typeof food !== 'undefined') sortNamedListInPlaceByUsd(food);
  if (typeof vehicles !== 'undefined') sortNamedListInPlaceByUsd(vehicles);
  if (typeof toys !== 'undefined') sortNamedListInPlaceByUsd(toys);
  if (typeof gifts !== 'undefined') sortNamedListInPlaceByUsd(gifts);
  if (typeof stickers !== 'undefined') sortNamedListInPlaceByUsd(stickers);
  if (typeof houses !== 'undefined') sortNamedListInPlaceByUsd(houses);

  const sortedPets = typeof pets !== 'undefined' ? sortItemsByUsdDesc(pets) : [];
  if (typeof petsByUsd !== 'undefined' && Array.isArray(petsByUsd)) {
    petsByUsd.splice(0, petsByUsd.length, ...sortedPets);
  } else if (typeof globalThis !== 'undefined') {
    globalThis.petsByUsd = sortedPets;
  }
}

var petsByUsd = typeof pets !== 'undefined' ? sortItemsByUsdDesc(pets) : [];
sortAllCatalogListsByUsd();
